        'json' =&gt; [
            'name' =&gt; 'consequatur',
            'email' =&gt; 'carolyne.luettgen@example.org',
            'password' =&gt; 'ij-e/dl4m',
            'password_confirmation' =&gt; 'yvddqamniihfqcoynlazghdtqtqxbajwbpilpmufinllwloauydlsmsjuryvojcybzvrbyickz',
        ],
    ]
);
$body = $response-&gt;getBody();
